import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.ktMMbWgA.js";const v=JSON.parse('{"title":"第 35 讲 · 反派视角 + 六个预测 — 对一门技术最深的理解是能同时复述两面 · 参考","description":"","frontmatter":{"title":"第 35 讲 · 反派视角 + 六个预测 — 对一门技术最深的理解是能同时复述两面 · 参考","act":6,"kind":"refs","prev":{"text":"L34 · 安全、红队与可解释性","link":"/lectures/L34-safety/references"},"next":false},"headers":[],"relativePath":"lectures/L35-predictions/references.md","filePath":"lectures/L35-predictions/references.md","lastUpdated":null}'),n={name:"lectures/L35-predictions/references.md"};function l(t,s,d,c,f,o){return a(),r("div",null,[...s[0]||(s[0]=[i('<h1 id="l35-references-反派视角-六个预测" tabindex="-1">L35 References: 反派视角 + 六个预测 <a class="header-anchor" href="#l35-references-反派视角-六个预测" aria-label="Permalink to &quot;L35 References: 反派视角 + 六个预测&quot;">​</a></h1><blockquote><p><strong>Lecture</strong>: 反派视角 + 六个预测 / &quot;Steelmanning the Skeptics + Six Predictions&quot; <strong>Course</strong>: Intelligence, Computed — From First Principles to Production AI Systems</p></blockquote><blockquote><p><strong>Last Verified</strong>: 2026-05-11 (links and citations checked; replace this when re-verifying)</p></blockquote><hr><section class="ref-card"><h2 class="ref-card-title" id="学术论文">1. 学术论文</h2><h3 class="ref-group" id="学术论文--gary-marcus-符号推理与神经网络的局限">Gary Marcus —— 符号推理与神经网络的局限</h3><ol class="ref-list"><li class="ref-item" id="ref-P1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P1</span><a class="ref-title" href="https://arxiv.org/abs/2002.06177" target="_blank" rel="noopener">The Next Decade in AI: Four Steps Towards Robust Artificial Intelligence</a></div><div class="ref-meta">Marcus, G. · 2020 · arXiv:2002.06177</div><p class="ref-desc"><strong>Core reference.</strong> Marcus 的完整技术路线图——为什么纯神经网络不够，神经-符号混合是出路。四步：混合模型、大规模知识库、因果推理、类比推理。</p></div></li><li class="ref-item" id="ref-P2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P2</span><a class="ref-title" href="https://arxiv.org/abs/1801.00631" target="_blank" rel="noopener">Deep Learning: A Critical Appraisal</a></div><div class="ref-meta">Marcus, G. · 2018 · arXiv:1801.00631</div><p class="ref-desc">十条深度学习系统性缺陷。Marcus 最被引用的技术批评文档。每条都有具体实验支撑。</p></div></li><li class="ref-item" id="ref-P3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P3</span><a class="ref-title" href="https://arxiv.org/abs/1711.00350" target="_blank" rel="noopener">Generalization without Systematicity: On the Compositional Skills of Sequence-to-Sequence RNNs</a></div><div class="ref-meta">Lake, B.M. &amp; Baroni, M. · 2018 · <em>ICML 2018</em></div><p class="ref-desc">SCAN 基准——证明 seq2seq 模型缺乏组合性泛化。Marcus 论点的实验支柱之一。</p></div></li><li class="ref-item" id="ref-P4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P4</span><a class="ref-title" href="https://arxiv.org/abs/2010.05465" target="_blank" rel="noopener">COGS: A Compositional Generalization Challenge Based on Semantic Interpretation</a></div><div class="ref-meta">Kim, N. &amp; Linzen, T. · 2020 · <em>EMNLP 2020</em></div><p class="ref-desc">COGS 基准——对 SCAN 的扩展，测试语义层面的组合性泛化。进一步验证了 Marcus 的系统性泛化批判。</p></div></li></ol><h3 class="ref-group" id="学术论文--yann-lecun-世界模型与超越自回归">Yann LeCun —— 世界模型与超越自回归</h3><ol class="ref-list"><li class="ref-item" id="ref-P5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P5</span><a class="ref-title" href="https://openreview.net/pdf?id=BZ5a1r-kVsf" target="_blank" rel="noopener">A Path Towards Autonomous Machine Intelligence</a></div><div class="ref-meta">LeCun, Y. · 2022 · OpenReview preprint</div><p class="ref-desc"><strong>Core reference.</strong> LeCun 的世界模型完整蓝图——JEPA 架构、分层规划、配置器模块。全讲 LeCun 部分的主要技术来源。</p></div></li><li class="ref-item" id="ref-P6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P6</span><a class="ref-title" href="https://arxiv.org/abs/2301.08243" target="_blank" rel="noopener">Self-Supervised Learning from Images with a Joint-Embedding Predictive Architecture</a></div><div class="ref-meta">Assran, M. et al. · 2023 · <em>CVPR 2023</em></div><p class="ref-desc">I-JEPA 论文——LeCun JEPA 愿景的首个具体实现（图像领域）。展示了在连续向量空间做预测而非像素空间重构。</p></div></li><li class="ref-item" id="ref-P7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P7</span><a class="ref-title" href="https://ai.meta.com/research/publications/revisiting-feature-prediction-for-learning-visual-representations-from-video/" target="_blank" rel="noopener">V-JEPA: Video Joint Embedding Predictive Architecture</a></div><div class="ref-meta">Bardes, A. et al. · 2024 · Meta AI Research</div><p class="ref-desc">V-JEPA——将 JEPA 扩展到视频。直接回应&quot;世界模型需要时序理解&quot;的需求。</p></div></li><li class="ref-item" id="ref-P8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P8</span><span class="ref-title">Objective-Driven AI: Towards AI Systems That Can Understand, Reason, Plan, and Learn</span></div><div class="ref-meta">LeCun, Y. · 2024 · Turing Lecture / Meta AI</div><p class="ref-desc">LeCun 2024 年对自回归 LLM 的最新批判——&quot;autoregressive LLMs are doomed&quot;系列演讲的学术版。</p></div></li></ol><h3 class="ref-group" id="学术论文--françois-chollet-arc-与智能度量">François Chollet —— ARC 与智能度量</h3><ol class="ref-list"><li class="ref-item" id="ref-P9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P9</span><a class="ref-title" href="https://arxiv.org/abs/1911.01547" target="_blank" rel="noopener">On the Measure of Intelligence</a></div><div class="ref-meta">Chollet, F. · 2019 · arXiv:1911.01547</div><p class="ref-desc"><strong>Core reference.</strong> Chollet 对&quot;什么是智能&quot;的完整定义——skill ≠ intelligence，智能 = 在新任务上的 few-shot 适应效率。ARC 基准的理论基础。</p></div></li><li class="ref-item" id="ref-P10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P10</span><a class="ref-title" href="https://arcprize.org" target="_blank" rel="noopener">ARC Prize 2024: Technical Report</a></div><div class="ref-meta">ARC Prize Foundation · 2024 · arcprize.org</div><p class="ref-desc">2024 ARC 竞赛结果——最佳成绩约 55%，来自 LLM + 程序搜索混合方法。纯 LLM 上限约 30-35%。</p></div></li><li class="ref-item" id="ref-P11"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P11</span><a class="ref-title" href="https://github.com/fchollet/ARC-AGI" target="_blank" rel="noopener">Program Synthesis for ARC: Combining LLMs with Symbolic Search</a></div><div class="ref-meta">Various (ARC Prize winners) · 2024 · ARC Prize 竞赛论文集</div><p class="ref-desc">2024 竞赛中表现最好的方法论文——展示了 LLM + 符号搜索的混合策略如何突破纯 LLM 的瓶颈。</p></div></li><li class="ref-item" id="ref-P11b"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P11b</span><a class="ref-title" href="https://arcprize.org" target="_blank" rel="noopener">ARC-AGI 2 / ARC Prize 2025</a></div><div class="ref-meta">ARC Prize Foundation · 2025 · arcprize.org/2025</div><div class="ref-links"><a class="ref-link" href="https://arcprize.org/2025" target="_blank" rel="noopener">arcprize.org/2025</a></div><p class="ref-desc">2025 年表 ARC 赛事——为逿辑推理模型升级，与 o3 / Claude Sonnet 4.5 交错产生的新一轮化。</p></div></li><li class="ref-item" id="ref-P11c"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P11c</span><a class="ref-title" href="https://arcprize.org/blog/oai-o3-pub-breakthrough" target="_blank" rel="noopener">OpenAI o3: Solving 87.5% of ARC-AGI</a></div><div class="ref-meta">OpenAI, 2024 · <a href="https://arcprize.org/blog/oai-o3-pub-breakthrough" target="_blank" rel="noopener">arcprize.org/blog/oai-o3-pub-breakthrough</a> · arcprize.org</div></div></li></ol><h3 class="ref-group" id="学术论文--具身智能-接地问题">具身智能 / 接地问题</h3><ol class="ref-list"><li class="ref-item" id="ref-P12"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P12</span><span class="ref-title">Intelligence without Representation</span></div><div class="ref-meta">Brooks, R.A. · 1991 · <em>Artificial Intelligence</em>, 47(1-3), 139-159</div><p class="ref-desc"><strong>Foundational.</strong> Brooks 的经典论文——智能不需要内部表征，行为从与环境的交互中涌现。&quot;Elephants Don&#39;t Play Chess&quot;的学术版。</p></div></li><li class="ref-item" id="ref-P13"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P13</span><span class="ref-title">The Symbol Grounding Problem</span></div><div class="ref-meta">Harnad, S. · 1990 · <em>Physica D</em>, 42(1-3), 335-346</div><p class="ref-desc">符号基础问题的经典表述——符号如何获得意义？中文房间论证的技术化版本。直接支撑具身派的论点。</p></div></li><li class="ref-item" id="ref-P14"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P14</span><span class="ref-title">The Free-Energy Principle: A Unified Brain Theory?</span></div><div class="ref-meta">Friston, K. · 2010 · <em>Nature Reviews Neuroscience</em>, 11, 127-138</div><p class="ref-desc">Friston 自由能原理——智能体通过最小化预测误差来理解世界，需要感知-行动循环。具身认知的理论基础之一。</p></div></li><li class="ref-item" id="ref-P15"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P15</span><span class="ref-title">Minds, Brains, and Programs</span></div><div class="ref-meta">Searle, J.R. · 1980 · <em>Behavioral and Brain Sciences</em>, 3(3), 417-424</div><p class="ref-desc">中文房间思想实验——操纵符号不等于理解意义。AI 哲学最被引用的论文之一。</p></div></li><li class="ref-item" id="ref-P16"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P16</span><a class="ref-title" href="https://global.oup.com/academic/product/the-oxford-handbook-of-4e-cognition-9780198735410" target="_blank" rel="noopener">4E Cognition: Embodied, Embedded, Enacted, Extended</a></div><div class="ref-meta">Newen, A., De Bruin, L. &amp; Gallagher, S. (eds.) · 2018 · Oxford University Press</div><p class="ref-desc">4E 认知框架的权威手册——认知是具身的、嵌入的、实行的、延展的。具身派论点的哲学基础。</p></div></li></ol><h3 class="ref-group" id="学术论文--预测方法论与预报">预测方法论与预报</h3><ol class="ref-list"><li class="ref-item" id="ref-P17"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P17</span><span class="ref-title">Forecasting AI Progress: A Research Agenda</span></div><div class="ref-meta">Gruetzemacher, R. &amp; Whittlestone, J. · 2022 · <em>Technological Forecasting and Social Change</em>, 181, 121796</div><p class="ref-desc">AI 预测方法论的学术综述——如何系统性地预测技术进步。六个预测的方法论基础。</p></div></li><li class="ref-item" id="ref-P18"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P18</span><a class="ref-title" href="https://arxiv.org/abs/2305.18223" target="_blank" rel="noopener">Predicting the Future of AI with AI: High-quality Link Prediction in an Exponentially Growing Knowledge Graph</a></div><div class="ref-meta">Krenn, M. et al. · 2023 · arXiv:2305.18223</div><p class="ref-desc">用 AI 知识图谱预测 AI 进步方向——有趣的元预测。</p></div></li><li class="ref-item" id="ref-P19"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">P19</span><a class="ref-title" href="https://www.routledge.com/Conjectures-and-Refutations-The-Growth-of-Scientific-Knowledge/Popper/p/book/9780415285940" target="_blank" rel="noopener"><strong>The Logic of Scientific Discovery</strong> · <em>Conjectures and Refutations</em></a></div><div class="ref-meta">Popper, K. · 1959 / 1963 · Hutchinson / Routledge</div><p class="ref-desc"><strong>Foundational.</strong> Popper 可证伪性原则（falsifiability）——科学陈述与非科学陈述的划界。本讲 6 预测与四元组（数据集 + 指标 + 阈值 + 判定主体）设计的哲学原则。§S35 明确引用。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="书籍">2. 书籍</h2><ol class="ref-list"><li class="ref-item" id="ref-B1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B1</span><span class="ref-title">Rebooting AI: Building Artificial Intelligence We Can Trust</span></div><div class="ref-meta">Marcus, G. &amp; Davis, E. · 2019 · Pantheon</div><p class="ref-desc"><strong>Primary text for Marcus section.</strong> 完整阐述了为什么当前深度学习不够、需要常识推理和符号操作。通俗但技术上诚实。</p></div></li><li class="ref-item" id="ref-B2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B2</span><span class="ref-title"><strong>Artificial General Intelligence</strong> (ed.)</span></div><div class="ref-meta">Goertzel, B. &amp; Pennachin, C. · 2007 · Springer</div><p class="ref-desc">AGI 概念的系统性学术探讨。用于&quot;什么是 AGI&quot;定义争论的背景。</p></div></li><li class="ref-item" id="ref-B3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B3</span><span class="ref-title">Superforecasting: The Art and Science of Prediction</span></div><div class="ref-meta">Tetlock, P.E. &amp; Gardner, D. · 2015 · Crown</div><p class="ref-desc"><strong>核心参考（预测方法论）</strong>。好预测的三个标准：具体、有时间节点、可被证伪。六个预测的元方法论来源。</p></div></li><li class="ref-item" id="ref-B4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B4</span><span class="ref-title">The Book of Why: The New Science of Cause and Effect</span></div><div class="ref-meta">Pearl, J. &amp; Mackenzie, D. · 2018 · Basic Books</div><p class="ref-desc">Pearl 的因果推理框架——深度学习缺乏因果理解是 Marcus 批判的支柱之一。通俗介绍因果阶梯。</p></div></li><li class="ref-item" id="ref-B5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B5</span><span class="ref-title"><strong>Deep Learning</strong> (textbook)</span></div><div class="ref-meta">Goodfellow, I., Bengio, Y. &amp; Courville, A. · 2016 · MIT Press</div><p class="ref-desc">第 1 章关于归纳偏置的讨论与 Chollet 的&quot;智能 = 适应效率&quot;形成对话。背景参考。</p></div></li><li class="ref-item" id="ref-B6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B6</span><span class="ref-title"><strong>The Embodied Mind: Cognitive Science and Human Experience</strong> (revised ed.)</span></div><div class="ref-meta">Varela, F.J., Thompson, E. &amp; Rosch, E. · 2016 (rev.) · MIT Press</div><p class="ref-desc">具身认知的奠基之作。4E 认知框架的哲学起源。</p></div></li><li class="ref-item" id="ref-B7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B7</span><span class="ref-title">Surfing Uncertainty: Prediction, Action, and the Embodied Mind</span></div><div class="ref-meta">Clark, A. · 2015 · Oxford University Press</div><p class="ref-desc">Andy Clark 的预测处理框架——大脑是预测机器，但需要身体来锚定预测。连接具身认知与计算神经科学。</p></div></li><li class="ref-item" id="ref-B8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B8</span><span class="ref-title">The Alignment Problem: Machine Learning and Human Values</span></div><div class="ref-meta">Christian, B. · 2020 · W.W. Norton</div><p class="ref-desc">对齐问题的通俗综述——与预测 5（AGI 定义争论）相关。</p></div></li><li class="ref-item" id="ref-B9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">B9</span><span class="ref-title">Possible Minds: Twenty-Five Ways of Looking at AI</span></div><div class="ref-meta">Brockman, J. (ed.) · 2019 · Penguin Press</div><p class="ref-desc">25 位顶级思想家对 AI 的不同看法——包括 Marcus、Pinker、Tegmark 等。多元视角的最佳集合。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="视频-talks">3. 视频 &amp; Talks</h2><h3 class="ref-group" id="视频-talks--gary-marcus">Gary Marcus</h3><ol class="ref-list"><li class="ref-item" id="ref-V1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V1</span><span class="ref-title">Gary Marcus: AI is Harder Than We Think</span></div><div class="ref-meta">TED / various · ~18 min</div><p class="ref-desc">Marcus 最通俗易懂的演讲版本。好的课前预习素材。</p></div></li><li class="ref-item" id="ref-V2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V2</span><span class="ref-title">Gary Marcus vs Yann LeCun Debate</span></div><div class="ref-meta">Munk Debates / NYU · ~90 min</div><p class="ref-desc">Marcus 和 LeCun 的直接辩论——两种哲学的正面交锋。可截取关键 5 分钟片段。</p></div></li></ol><h3 class="ref-group" id="视频-talks--yann-lecun">Yann LeCun</h3><ol class="ref-list"><li class="ref-item" id="ref-V3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V3</span><span class="ref-title">Yann LeCun: Objective-Driven AI (Turing Lecture 2024)</span></div><div class="ref-meta">ACM / Meta AI · ~60 min</div><p class="ref-desc"><strong>核心视频。</strong> LeCun 对 JEPA 和世界模型最完整的阐述。可截取&quot;autoregressive is doomed&quot;片段。</p></div></li><li class="ref-item" id="ref-V4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V4</span><span class="ref-title">Yann LeCun: From Machine Learning to Autonomous Intelligence</span></div><div class="ref-meta">Meta AI / various · ~45 min</div><p class="ref-desc">LeCun 反复迭代的世界模型演讲——不同版本侧重点不同，选最新的。</p></div></li><li class="ref-item" id="ref-V5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V5</span><a class="ref-title" href="https://www.youtube.com/watch?v=5t1vTLU7s40" target="_blank" rel="noopener">Yann LeCun Interview on Lex Fridman Podcast</a></div><div class="ref-meta">Lex Fridman · ~3 hrs</div><p class="ref-desc">长对话中有大量对自回归批判的细节论述。时间戳可参考。</p></div></li></ol><h3 class="ref-group" id="视频-talks--françois-chollet">François Chollet</h3><ol class="ref-list"><li class="ref-item" id="ref-V6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V6</span><span class="ref-title">François Chollet: On the Measure of Intelligence (talk)</span></div><div class="ref-meta">~40 min</div><p class="ref-desc">Chollet 论文的演讲版——比论文更容易消化。Skill vs Intelligence 的区分最清晰。</p></div></li><li class="ref-item" id="ref-V7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V7</span><a class="ref-title" href="https://arcprize.org" target="_blank" rel="noopener">ARC Prize Announcement &amp; Results</a></div><div class="ref-meta">ARC Prize Foundation · ~30 min</div><p class="ref-desc">2024 ARC 竞赛结果——展示当前最好的 AI 系统在 ARC 上的表现。</p></div></li><li class="ref-item" id="ref-V8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V8</span><span class="ref-title">François Chollet: Why General Intelligence Has Not Been Achieved</span></div><div class="ref-meta">Dwarkesh Patel Podcast · ~2 hrs</div><p class="ref-desc">深度对话——Chollet 对 LLM 局限性的技术细节论述。</p></div></li></ol><h3 class="ref-group" id="视频-talks--具身智能综合">具身智能综合</h3><ol class="ref-list"><li class="ref-item" id="ref-V9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V9</span><span class="ref-title">Rodney Brooks: Intelligence Without Representation (classic talk)</span></div><div class="ref-meta">MIT / Various · ~45 min</div><p class="ref-desc">Brooks 具身智能理念的经典演讲。历史性资料。</p></div></li><li class="ref-item" id="ref-V10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">V10</span><span class="ref-title">Karl Friston: The Free Energy Principle</span></div><div class="ref-meta">~60 min</div><p class="ref-desc">Friston 自由能原理演讲——抽象但对理解具身认知框架至关重要。可选。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="博客与文章">4. 博客与文章</h2><ol class="ref-list"><li class="ref-item" id="ref-A1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A1</span><a class="ref-title" href="https://nautil.us/deep-learning-is-hitting-a-wall-238440/" target="_blank" rel="noopener">Deep Learning Is Hitting a Wall</a></div><div class="ref-meta">Gary Marcus</div><p class="ref-desc">Marcus 最具影响力的公共批评文章——通俗、尖锐、引发大量讨论。好的课前阅读。</p></div></li><li class="ref-item" id="ref-A2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A2</span><span class="ref-title">AI&#39;s Next Big Challenge: Understanding the World</span></div><div class="ref-meta">Yann LeCun (interviews)</div><p class="ref-desc">LeCun 关于世界模型的公开阐述集合。</p></div></li><li class="ref-item" id="ref-A3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A3</span><a class="ref-title" href="https://chollet.substack.com/" target="_blank" rel="noopener">The ARC Challenge: Why It Matters</a></div><div class="ref-meta">François Chollet (blog/tweets)</div><p class="ref-desc">Chollet 关于 ARC 设计理念的系列推文和博客——比论文更易读。</p></div></li><li class="ref-item" id="ref-A4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A4</span><span class="ref-title">Elephants Don&#39;t Play Chess</span></div><div class="ref-meta">Brooks, R.A.</div><p class="ref-desc">Brooks 的经典论文——标题即论点。&quot;大象不下棋，但大象很聪明。&quot;</p></div></li><li class="ref-item" id="ref-A5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A5</span><span class="ref-title">Sparks of AGI? AutoGPT, ChaosGPT, and the Unhinged Frontier</span></div><p class="ref-desc">2023-2024 年 AGI 争论的生态——乐观派 vs 怀疑派的公共辩论。用于预测 5 的背景。</p></div></li><li class="ref-item" id="ref-A6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A6</span><a class="ref-title" href="https://www.gjopen.com/" target="_blank" rel="noopener">Philip Tetlock&#39;s Good Judgment Project</a></div><div class="ref-meta">Good Judgment Inc.</div><p class="ref-desc">Tetlock 超级预测者项目——好预测方法论的来源。推荐观众注册体验。</p></div></li><li class="ref-item" id="ref-A7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A7</span><span class="ref-title">Neurosymbolic AI: The Third Wave</span></div><div class="ref-meta">Garcez, A.d. &amp; Lamb, L.C.</div><p class="ref-desc">神经-符号混合 AI 的学术综述——Marcus 提出的替代方案的技术现状。</p></div></li><li class="ref-item" id="ref-A8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A8</span><a class="ref-title" href="https://aiimpacts.org/" target="_blank" rel="noopener">AI Forecasting: What Do the Experts Think?</a></div><div class="ref-meta">Various (AI Impacts, Metaculus)</div><div class="ref-links"><a class="ref-link" href="https://www.metaculus.com/questions/?search=AGI" target="_blank" rel="noopener">metaculus.com</a></div><p class="ref-desc">集体预测平台——AGI 时间线、重大突破的群体预测。六个预测的外部校准来源。</p></div></li><li class="ref-item" id="ref-A9"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A9</span><span class="ref-title">Situational Awareness: The Decade Ahead</span></div><div class="ref-meta">Leopold Aschenbrenner</div><p class="ref-desc"><a href="https://situational-awareness.ai/" target="_blank" rel="noopener">situational-awareness.ai</a></p></div></li><li class="ref-item" id="ref-A10"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A10</span><span class="ref-title">AI 2027: A Detailed AGI Scenario</span></div><div class="ref-meta">Daniel Kokotajlo et al.</div><p class="ref-desc"><a href="https://ai-2027.com/" target="_blank" rel="noopener">ai-2027.com</a></p></div></li><li class="ref-item" id="ref-A11"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A11</span><span class="ref-title">Anthropic · Machines of Loving Grace</span></div><div class="ref-meta">Dario Amodei</div><p class="ref-desc"><a href="https://darioamodei.com/machines-of-loving-grace" target="_blank" rel="noopener">darioamodei.com/machines-of-loving-grace</a></p></div></li><li class="ref-item" id="ref-A12"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A12</span><span class="ref-title">Sam Altman · Three Observations</span></div><div class="ref-meta">Sam Altman</div><p class="ref-desc"><a href="https://blog.samaltman.com/three-observations" target="_blank" rel="noopener">blog.samaltman.com</a></p></div></li><li class="ref-item" id="ref-A13"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">A13</span><a class="ref-title" href="https://metr.org/blog/2025-03-19-measuring-ai-ability-to-complete-long-tasks/" target="_blank" rel="noopener">METR · Measuring AI Ability to Complete Long Tasks</a></div><div class="ref-meta">METR Research, 2025</div><p class="ref-desc">METR 2025 年 3 月论文讱载论讲稿中「2027」预测的数据参考。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="arc-基准资源">5. ARC 基准资源</h2><ol class="ref-list"><li class="ref-item" id="ref-R1"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">R1</span><a class="ref-title" href="https://github.com/fchollet/ARC-AGI" target="_blank" rel="noopener">ARC-AGI GitHub Repository</a></div><p class="ref-desc">原始数据集 + 可视化工具。课堂展示 ARC 题目的直接来源。</p></div></li><li class="ref-item" id="ref-R2"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">R2</span><a class="ref-title" href="https://arcprize.org" target="_blank" rel="noopener">ARC Prize Official Site</a></div><p class="ref-desc">$1M 奖金竞赛——当前排行榜 + 获胜方法论文。</p></div></li><li class="ref-item" id="ref-R3"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">R3</span><a class="ref-title" href="https://lab42.global/arc/" target="_blank" rel="noopener">ARC Interactive Playground</a></div><p class="ref-desc">在线尝试 ARC 题目——课堂互动最佳工具。让观众亲自体验。</p></div></li><li class="ref-item" id="ref-R4"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">R4</span><span class="ref-title">ARC Leaderboard &amp; Analysis</span></div><p class="ref-desc">各方法在 ARC 上的得分对比——纯 LLM vs 混合方法 vs 程序搜索。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="预测平台与校准资源">6. 预测平台与校准资源</h2><ol class="ref-list"><li class="ref-item" id="ref-R5"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">R5</span><a class="ref-title" href="https://www.metaculus.com/questions/?search=AI" target="_blank" rel="noopener">Metaculus AI Questions</a></div><p class="ref-desc">群体预测平台——包含大量 AI 相关预测问题（AGI 时间线、基准突破等）。</p></div></li><li class="ref-item" id="ref-R6"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">R6</span><a class="ref-title" href="https://aiimpacts.org/" target="_blank" rel="noopener">AI Impacts</a></div><p class="ref-desc">AI 进度追踪——历史基准表现、专家调查、时间线估计的系统性收集。</p></div></li><li class="ref-item" id="ref-R7"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">R7</span><a class="ref-title" href="https://epochai.org/" target="_blank" rel="noopener">Epoch AI</a></div><p class="ref-desc">AI 训练计算量、数据集大小、参数量的趋势追踪——预测的数据基础。</p></div></li><li class="ref-item" id="ref-R8"><span class="ref-stars ref-stars--none" aria-hidden="true"></span><div class="ref-body"><div class="ref-head"><span class="ref-id">R8</span><a class="ref-title" href="https://ourworldindata.org/artificial-intelligence" target="_blank" rel="noopener">Our World in Data: AI</a></div><p class="ref-desc">AI 能力增长的可视化数据——好的课堂图表来源。</p></div></li></ol></section><section class="ref-card"><h2 class="ref-card-title" id="阅读优先级">阅读优先级</h2><h3 class="ref-group" id="阅读优先级--必读-课前准备">必读（课前准备）</h3><p class="ref-prose">1. <strong>P9</strong> — Chollet, <em>On the Measure of Intelligence</em>（核心论文，定义了&quot;什么是智能&quot;的框架）</p><p class="ref-prose">2. <strong>P5</strong> — LeCun, <em>A Path Towards Autonomous Machine Intelligence</em>（世界模型蓝图）</p><p class="ref-prose">3. <strong>P2</strong> — Marcus, <em>Deep Learning: A Critical Appraisal</em>（十条系统性批判）</p><p class="ref-prose">4. <strong>B3</strong> — Tetlock, <em>Superforecasting</em>（预测方法论）</p><h3 class="ref-group" id="阅读优先级--推荐-深化理解">推荐（深化理解）</h3><p class="ref-prose">5. <strong>P1</strong> — Marcus, <em>Four Steps Towards Robust AI</em></p><p class="ref-prose">6. <strong>P12</strong> — Brooks, <em>Intelligence without Representation</em></p><p class="ref-prose">7. <strong>B1</strong> — Marcus &amp; Davis, <em>Rebooting AI</em></p><p class="ref-prose">8. <strong>V3</strong> — LeCun Turing Lecture 2024</p><p class="ref-prose">9. <strong>V6</strong> — Chollet, <em>On the Measure of Intelligence</em> (talk)</p><h3 class="ref-group" id="阅读优先级--延伸-高级读者">延伸（高级读者）</h3><p class="ref-prose">10. <strong>P14</strong> — Friston, <em>Free-Energy Principle</em></p><p class="ref-prose">11. <strong>P15</strong> — Searle, <em>Minds, Brains, and Programs</em></p><p class="ref-prose">12. <strong>B6</strong> — Varela et al., <em>The Embodied Mind</em></p><p class="ref-prose">13. <strong>P17</strong> — Gruetzemacher, <em>Forecasting AI Progress</em></p></section>',11)])])}const h=e(n,[["render",l]]);export{v as __pageData,h as default};
